        <div id="orderSummary" class="fixed bottom-[68px] left-1/2 z-40 hidden w-[calc(100%-1.5rem)] max-w-[500px] -translate-x-1/2 items-center justify-between gap-3 rounded-xl border border-ink/40 bg-ink p-3 text-white shadow-xl"><button id="closeOrderSummary" type="button" aria-label="Close order summary" class="absolute -right-2 -top-2 flex h-7 w-7 items-center justify-center rounded-full bg-white text-lg font-bold text-ink shadow">×</button><div><p class="text-[10px] uppercase tracking-wider text-white/70">Current Commissary Draft</p><p id="summaryText" class="mt-0.5 text-sm font-bold">0 Items Selected</p><p id="summaryTotal" class="font-display font-bold text-yellow">$0.00</p></div><a href="{{ route('cart') }}" class="flex shrink-0 items-center gap-1.5 rounded-lg bg-yellow px-4 py-2.5 text-sm font-bold text-[#101010]">Checkout<span class="material-symbols-outlined text-sm">arrow_forward</span></a></div>
