    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const frequentSection = [...document.querySelectorAll('section')].find((section) => section.textContent.includes('Frequently Ordered'));
            if (frequentSection) frequentSection.classList.add('hidden');
            const deliverySubtitle = [...document.querySelectorAll('p')].find((element) => element.textContent.includes('Central Commissary'));
            if (deliverySubtitle) deliverySubtitle.remove();
            const cutoffBadge = [...document.querySelectorAll('div')].find((element) => element.textContent.includes('Fast Cut-Off 22:00') && element.textContent.length < 40);
            if (cutoffBadge) cutoffBadge.remove();
            const summary = document.getElementById('orderSummary');
            const text = document.getElementById('summaryText');
            const total = document.getElementById('summaryTotal');
            document.getElementById('closeOrderSummary').addEventListener('click', () => { summary.classList.add('hidden'); summary.classList.remove('flex'); });
            const search = document.getElementById('productSearch');
            const products = [...document.querySelectorAll('#productList article')];
            const cartKey = 'vibe-cart-items-{{ md5($email) }}';
            const removedKey = 'vibe-cart-removed-items';
            const getCart = () => JSON.parse(localStorage.getItem(cartKey) || '[]');
            const headerCartText = [...document.querySelectorAll('header button')].find((button) => button.querySelector('.material-symbols-outlined')?.textContent.trim() === 'shopping_cart')?.querySelector('span:last-child');
            const updateHeaderCart = () => { const cart = getCart(); const count = cart.reduce((sum, item) => sum + Number(item.quantity || 0), 0); const value = cart.reduce((sum, item) => sum + (Number(item.price || 0) * Number(item.quantity || 0)), 0); if (headerCartText) headerCartText.textContent = `${count} • ₱${value.toFixed(2)}`; };
            updateHeaderCart();
            getCart().forEach((item) => { const product = products.find((entry) => entry.dataset.sku === item.sku); if (product) product.querySelector('.quantity').value = item.quantity; });
            const saveProduct = (product, quantity) => {
                const cart = getCart().filter((item) => item.sku !== product.dataset.sku);
                if (quantity > 0) cart.push({ sku: product.dataset.sku, name: product.dataset.name, price: Number(product.dataset.price), quantity, image: product.dataset.image, unit: product.dataset.unit });
                localStorage.setItem(cartKey, JSON.stringify(cart));
                const removed = new Set(JSON.parse(localStorage.getItem(removedKey) || '[]'));
                removed.delete(product.dataset.sku);
                localStorage.setItem(removedKey, JSON.stringify([...removed]));
                updateHeaderCart();
            };
            const refresh = () => { let count = 0; let value = 0; products.forEach((product) => { const quantity = Number(product.querySelector('.quantity').value); count += quantity; value += quantity * Number(product.dataset.price); }); summary.classList.toggle('hidden', count === 0); summary.classList.toggle('flex', count > 0); text.textContent = `${count} Item${count === 1 ? '' : 's'} Selected`; total.textContent = `₱${value.toFixed(2)}`; };
            products.forEach((product) => { const input = product.querySelector('.quantity'); product.querySelector('.quantity-minus').addEventListener('click', () => { input.value = Math.max(0, Number(input.value) - 1); saveProduct(product, Number(input.value)); refresh(); }); product.querySelector('.quantity-plus').addEventListener('click', () => { input.value = Number(input.value) + 1; saveProduct(product, Number(input.value)); refresh(); }); product.querySelector('.add-product').addEventListener('click', () => { input.value = Number(input.value) + 1; saveProduct(product, Number(input.value)); refresh(); }); });
            search.addEventListener('input', () => { const query = search.value.toLowerCase(); products.forEach((product) => { product.classList.toggle('hidden', !product.textContent.toLowerCase().includes(query)); }); });
            let selectedCategory = 'All';
            const categoryButtons = [...document.querySelectorAll('button')].filter((button) => ['All (52)', '🍗 Frozen Products', '🍟 Dry Goods', '🥫 Sauces & Marinades', '📦 Packaging', '🧼 Equipments & Uniforms'].includes(button.textContent.trim()));
            const matchesCategory = (product, category) => {
                const content = product.textContent.toLowerCase();
                if (category === 'All') return true;
                if (product.dataset.category) return product.dataset.category === category; if (category === 'Frozen Products') return /chicken|wings|tenders|siomai|pastil/.test(content);
                if (category === 'Dry Goods') return product.dataset.category === 'Dry Goods';
                if (category === 'Sauces & Marinades') return product.dataset.category === 'Sauces & Marinades' || /sauce|glaze|rub|dip|mustard/.test(content);
                if (category === 'Packaging') return product.dataset.category === 'Packaging' || /box|packaging|carton|clamshell|plastic|paper|glove|cup/.test(content);
                return product.dataset.category === 'Equipments & Uniforms' || /clean|hygiene|sanitation|burner|wok|warmer|table|chair|plate|uniform|shirt|cap|apron|tag|stamp|ink/.test(content);
            };
            const applyFilters = () => { const query = search.value.toLowerCase(); products.forEach((product) => { product.classList.toggle('hidden', !matchesCategory(product, selectedCategory) || !product.textContent.toLowerCase().includes(query)); }); };
            categoryButtons.forEach((button) => { button.addEventListener('click', () => { selectedCategory = button.textContent.trim().startsWith('All') ? 'All' : button.textContent.trim().replace(/^[^A-Za-z]+/, '').replace(/\s+\(\d+\)$/, ''); categoryButtons.forEach((item) => item.classList.remove('bg-yellow', 'font-bold')); button.classList.add('bg-yellow', 'font-bold'); applyFilters(); }); });
            search.addEventListener('input', applyFilters);
        });
    </script>
    <script>document.addEventListener('DOMContentLoaded', () => { const w = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT); let n; while (n = w.nextNode()) { if (!n.parentElement.closest('script,style')) n.nodeValue = n.nodeValue.replaceAll('$', '₱'); } });</script>
</body>
</html>















